import re
from pathlib import Path

SEP = r"[ \t\-()]*"
PATTERN = re.compile(
    r"(?<!\d)\+?"
    r"(?:3" + SEP + "8" + SEP + "0|0)"
    r"(?:" + SEP + r"\d){9}"
    r"(?!\d)"
)


def normalize(raw: str) -> str:
    digits = re.sub(r"\D", "", raw)
    if digits.startswith("380"):
        return "+" + digits
    return "+38" + digits


def main() -> None:
    text = Path("дані/контакти.txt").read_text(encoding="utf-8", errors="replace")
    numbers = {normalize(m.group(0)) for m in PATTERN.finditer(text)}
    for number in sorted(numbers):
        print(number)


if __name__ == "__main__":
    main()
